def detect_file_mime_type(path):
    ext = os.path.splitext(path)[1].lower()
    filename = os.path.basename(path)

    mime = mimetypes.MimeTypes()

    # Guess the mime type from the extension
    mime_type = mime.guess_type(urllib.pathname2url(path))[0]

    # If this didn't work try looking up the extension in any case
    # (some extensions are only listed in upper case)
    if mime_type is None:
        mime_type = mime.guess_type(urllib.pathname2url(ext))[0]

    mapping = {
        '.log': 'text/plain',
        '.TXT': 'text/plain',
        '.LOG': 'text/plain'
    }

    # Still nothing? Try a manual lookup for some common file types
    if mime_type is None:
        return mapping.get(ext)

    return mime_type


