import numpy as np
from numpy import testing

from chainer import cuda
from chainer import functions


class Copy(unittest.TestCase):

    def setUp(self):
        self.x_cpu = np.random.randn(3, 2).astype(np.float32)
        self.x_gpu = cuda.to_gpu(self.x_cpu)

    def check_forward_copy(self, x, dst):
        dst_is_host = isinstance(dst, int) and dst >= 0
        if dst_is_host:
            dst = cuda.Device(dst)
        if dst_is_host or cuda.cupy is None:
            self.assertEqual(x.device, dst)
            testing.assert_array_equal(x, functions.copy(x, dst).data)
        else:
            self.assertEqual(x.device, cuda.GpuDevice(None))
            testing.assert_array_equal(
                x.copy_to_host(),
                functions.copy(x, dst).data.get_device().copy_to_host())

    def test_forward_copy_cpu(self):
        self.check_forward_copy(self.x_cpu, -1)

    def test_forward_copy_gpu(self):
        dst_dev = cuda.Device(self.x_gpu.device.id)
        self.check_forward_copy(self.x_gpu, dst_dev)

    def test_forward_copy_host(self):
        self.check_forward_copy(self.x_gpu, 0)

    def test_backward(self):
        dst_dev = cuda.Device(0)
        x_gpu = self.x_gpu.copy()
        x_gpu.unchange_grad()
        tgt = functions.copy(x_gpu, dst_dev)
        tgt backward = tgt.grad

        testing.assert_array_equal(
            tgt.grad,
            cuda.to_cpu(tgt.unchange_grad().copy_to_host()))


