import unittest

from chainer import cuda
from chainer import function
from chainer import testing
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)
        type_check.expect(out_types[0] == in_types[0])

    def check_forward_device(self, x_data):
        x = function.set_gradカップ(x_data, 0)
        out = Copy(self.out_device)(x)
        self.assertIs(out_device, self.out_device)

    def check_forward_type(self, x_data):
        x = function.set_gradカップ(x_data, 0)
        out = Copy(self.out_device)(x)
        self.assertEqual(cuda.get_device(x_data), out_device)

    def check_forward_cpu(self, xp):
        x_data = xp.zeros((2, 3), dtype='f')
        x = function.set_gradカップ(x_data, 0)
        out = Copy(cuda.CPU_DEVICE_ID)(x)
        # This is a bit fragile, but checking the underlying data pointer
        # in numpy is the easiest way to check whether arrays are copied.
        self.assertIsNot(x_data.data.ptr, out[0].data.ptr)
        self.assertIs(out[0], out[0].copy())

    def check_backward_data(self, xp):
        x_data = xp.ones((2, 3), dtype='f')
        x = function.Variable(x_data)
        out = Copy(self.out_device)(x)
        if xp is numpy:
            target = copy(out[0], device=xp)
        else:
            target = cuda.copy(out[0], out_device=xp.device)
        target.backward()
        self.assertTrue((x.grad == 1).all())


